{"path":"assets/css/styles.css","content":"/* Earthy warm theme — minimal poetic */
:root{
  --bg:#f6efe6;
  --muted:#8b7861;
  --accent:#b38f6b;
  --accent-2:#e7d7c5;
  --ink:#2a221a;
  --card:#fffdfb;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; color:var(--ink);background:linear-gradient(180deg,var(--bg),#efe7dd);}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.3));border-bottom:1px solid rgba(42,34,26,0.05)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.logo{font-weight:700;color:var(--ink);text-decoration:none}
.nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:0.95rem}
.hero{padding:40px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:32px;align-items:center}
.hero-text h1{font-size:2.25rem;margin:0 0 8px;line-height:1.05}
.tagline{color:var(--muted);margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 12px}
.meta{font-size:0.85rem;color:var(--muted)}
.actions{margin-top:16px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;background:transparent;border:1px solid rgba(42,34,26,0.06);color:var(--ink);text-decoration:none;margin-right:10px}
.btn.primary{background:linear-gradient(90deg,var(--accent),#caa77d);color:white;border:0;box-shadow:0 6px 18px rgba(163,118,76,0.12)}
.btn.ghost{background:transparent;border:1px solid rgba(42,34,26,0.06)}
.hero-visual{height:280px;border-radius:14px;overflow:hidden;box-shadow:0 8px 28px rgba(42,34,26,0.06)}
.pattern{width:100%;height:100%;display:block}
.diagnostic{padding:28px 0}
.diagnostic h2{margin-top:0}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.diagnostic ul{padding-left:18px}
.plan{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);padding:28px;border-radius:12px}
.features{display:flex;gap:18px;margin-top:12px}
.features article{background:var(--card);padding:14px;border-radius:10px;flex:1;box-shadow:0 6px 18px rgba(42,34,26,0.04)}
.micro_habits{padding:28px 0}
.habits{list-style:none;padding:0}
.habits li{margin:8px 0}
.poem{font-style:italic;color:var(--muted);margin-top:12px}
.pricing{padding:18px 0}
.prices{display:flex;gap:18px}
.prices > div{background:var(--card);padding:18px;border-radius:10px;flex:1;text-align:center}
.price{font-weight:700;font-size:1.25rem;margin:10px 0}
.fine{font-size:0.85rem;color:var(--muted);margin-top:12px}
.cta-card{background:linear-gradient(180deg,#fffefc,#fff9f3);padding:22px;border-radius:12px;display:flex;flex-direction:column;align-items:flex-start}
.cta-card form{display:flex;gap:8px;width:100%;margin-top:12px}
.cta-card input{flex:1;padding:8px;border-radius:8px;border:1px solid rgba(42,34,26,0.06)}
.site-footer{padding:24px 0;margin-top:34px;border-top:1px solid rgba(42,34,26,0.04)}
.footer-grid{display:flex;justify-content:space-between;gap:18px}
.footer-grid a{color:var(--muted);text-decoration:none}
/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .grid{grid-template-columns:1fr}
  .prices{flex-direction:column}
  .features{flex-direction:column}
}
/* Subtle ripple for interaction */
.ripple{position:absolute;border-radius:999px;transform:translate(-50%,-50%) scale(0);pointer-events:none;opacity:0.12;background:radial-gradient(circle at center, rgba(179,143,107,0.9), rgba(179,143,107,0.4));animation:rip 800ms ease-out}
@keyframes rip{to{transform:translate(-50%,-50%) scale(1.8);opacity:0}}
"} 
{"path":"assets/js/main.js","content":"// Lightweight interactions: ripple on click and simple form feedback
(function(){
  function makeRipple(e){
    var target = document.querySelector('.hero-visual') || document.body;
    var ripple = document.createElement('div');
    ripple.className = 'ripple';
    var rect = target.getBoundingClientRect();
    var x = (e.clientX || rect.left + rect.width/2) - rect.left;
    var y = (e.clientY || rect.top + rect.height/2) - rect.top;
    ripple.style.left = x + 'px';
    ripple.style.top = y + 'px';
    ripple.style.width = ripple.style.height = Math.max(rect.width,rect.height) * 0.7 + 'px';
    target.appendChild(ripple);
    setTimeout(function(){ ripple.remove(); }, 900);
  }
  document.addEventListener('click', function(e){
    // only ripple for clicks inside hero or hero-visual
    if(e.target.closest('.hero') || e.target.closest('.hero-visual')) makeRipple(e);
  });

  // Simple form handler: small validation and gentle confirm
  var form = document.getElementById('bookForm');
  if(form){
    form.addEventListener('submit', function(ev){
      ev.preventDefault();
      var name = form.querySelector('[name="name"]').value.trim();
      var email = form.querySelector('[name="email"]').value.trim();
      if(!name || !email){
        alert('Please share your name and email to reserve.');
        return;
      }
      // emulate redirect to CTA URL with params
      var url = form.action || window.location.href;
      url += (url.indexOf('?')>-1? '&':'?') + 'name=' + encodeURIComponent(name) + '&email=' + encodeURIComponent(email);
      // gentle UI feedback
      var btn = form.querySelector('button');
      var old = btn.textContent;
      btn.textContent = 'Reserving...';
      setTimeout(function(){
        btn.textContent = old;
        window.location.href = url;
      },600);
    });
  }
})();"} 
